import PDFKit
import QuickLookThumbnailing
import SwiftUI

// MARK: - File thumbnail

/// First-page thumbnail of a PDF file, generated by Quick Look and cached by the system.
struct FileThumbnail: View {
    let url: URL
    var width: CGFloat = 36

    @Environment(\.displayScale) private var displayScale
    @State private var image: UIImage?

    private var height: CGFloat { (width * 1.3).rounded() }

    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: width * 0.14, style: .continuous)
                .fill(Color.white)
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                Image(systemName: "doc.text")
                    .font(.system(size: width * 0.4))
                    .foregroundStyle(.gray.opacity(0.5))
            }
        }
        .frame(width: width, height: height)
        .clipShape(RoundedRectangle(cornerRadius: width * 0.14, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: width * 0.14, style: .continuous)
                .strokeBorder(.black.opacity(0.12), lineWidth: 0.5)
        }
        .shadow(color: .black.opacity(0.08), radius: 1.5, y: 1)
        .accessibilityHidden(true)
        .task(id: url) {
            let request = QLThumbnailGenerator.Request(
                fileAt: url,
                size: CGSize(width: width, height: height),
                scale: displayScale,
                representationTypes: .thumbnail
            )
            if let representation = try? await QLThumbnailGenerator.shared.generateBestRepresentation(for: request) {
                image = representation.uiImage
            }
        }
    }
}

// MARK: - Page thumbnails

/// Renders page thumbnails for one document. An actor keeps PDFKit off the main thread
/// and serializes access to the shared PDFDocument.
actor PageThumbnailLoader {
    private let document: PDFDocument?
    private let cache = NSCache<NSNumber, UIImage>()

    init(url: URL) {
        document = PDFDocument(url: url)
    }

    func thumbnail(page: Int, size: CGSize) -> UIImage? {
        if let cached = cache.object(forKey: NSNumber(value: page)) { return cached }
        guard let pdfPage = document?.page(at: page - 1) else { return nil }
        let image = pdfPage.thumbnail(of: size, for: .cropBox)
        cache.setObject(image, forKey: NSNumber(value: page))
        return image
    }
}

/// One page of a document, used in the Split page grid.
struct PageThumbnail: View {
    let loader: PageThumbnailLoader
    let page: Int

    @State private var image: UIImage?

    var body: some View {
        ZStack {
            Color.white
            if let image {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFit()
            } else {
                ProgressView()
                    .controlSize(.small)
                    .tint(.gray)
            }
        }
        .aspectRatio(0.77, contentMode: .fit)
        .clipShape(RoundedRectangle(cornerRadius: 6, style: .continuous))
        .task(id: page) {
            image = await loader.thumbnail(page: page, size: CGSize(width: 240, height: 312))
        }
    }
}
